{
  "$schema": "https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json",
  "name": "io.github.llmsresearch/paperbanana",
  "title": "PaperBanana",
  "description": "Generate academic diagrams and statistical plots from text using multi-agent AI.",
  "version": "0.3.0",
  "packages": [
    {
      "registryType": "pypi",
      "identifier": "paperbanana",
      "version": "0.3.0",
      "transport": {
        "type": "stdio"
      }
    }
  ],
  "repository": {
    "url": "https://github.com/llmsresearch/paperbanana",
    "source": "github"
  },
  "tools": [
    {
      "name": "generate_diagram",
      "description": "Generate a methodology diagram from text context and caption"
    },
    {
      "name": "continue_run",
      "description": "Continue refinement for an existing run directory (optional critic feedback)"
    },
    {
      "name": "generate_plot",
      "description": "Generate a statistical plot from JSON data and intent description"
    },
    {
      "name": "evaluate_diagram",
      "description": "Compare a generated diagram against a human reference on 4 dimensions"
    },
    {
      "name": "evaluate_plot",
      "description": "Compare a generated statistical plot against a human reference on 4 dimensions"
    }
  ]
}
